@dataclass(frozen=True)
class CategoryProfile:
    """카테고리 하나의 특성 프롬프트 묶음."""
    key: str
    label: str
    system_body: str          # COMMON_SYSTEM_PREAMBLE 뒤에 붙는 카테고리 특성 시스템 프롬프트
    writing_guideline: str    # [작성 지침] 본문
    base_rules: tuple         # [점수 판단 규칙] 공통 기본 규칙
    life_stage: dict          # life_stage 레벨별 추가 규칙
    trait_rules: dict         # 그 외 보조 변수 레벨별 추가 규칙
    system_preamble: str = None   # 이 카테고리만의 프리앰블(없으면 COMMON_SYSTEM_PREAMBLE 사용)


