class OpenAIPersonaReactionClient:
    JSON_SCHEMA = {
        "type": "object",
        "additionalProperties": False,
        "properties": {
            "satisfaction_score": {
                "type": "integer",
                "minimum": 1,
                "maximum": 5,
            },
            "one_line_opinion": {
                "type": "string",
                "description": "정책에 대한 입장과 생활상의 이유를 밝히는 자연스러운 존댓말 주민 의견",
            },
            "key_keywords": {
                "type": "array",
                "items": {"type": "string"},
                "description": "정책 소재가 아닌, 본인이 걱정하거나 기대하는 이유의 초점이 되는 핵심 명사 1개. 교통 정책 예: 이용권 부족, 배차 간격, 정산 절차, 동승 편익, 병원 접근성, 재정 지속성",
            },
        },
        "required": [
            "satisfaction_score",
            "one_line_opinion",
            "key_keywords",
        ],
    }

    def __init__(
        self,
        model: str = "gpt-4.1-mini",
        api_key_env: str = "OPENAI_API_KEY",
        max_retries: int = 2,
        retry_sleep_seconds: float = 1.5,
    ):
        self.model = model
        self.api_key_env = api_key_env
        self.max_retries = max_retries
        self.retry_sleep_seconds = retry_sleep_seconds
        self.prompt_builder = PersonaPromptBuilder()
        self.client = self._build_client()

    def _build_client(self) -> Any:
        load_env_file()
        api_key = os.getenv(self.api_key_env)
        if not api_key:
            raise RuntimeError(
                f"{self.api_key_env} 환경변수가 없습니다. 예: export {self.api_key_env}='sk-...'"
            )
        try:
            from openai import OpenAI
        except ModuleNotFoundError as exc:
            raise RuntimeError(
                "openai 패키지가 설치되어 있지 않습니다. "
                "다음 명령으로 설치하세요: python -m pip install openai"
            ) from exc
        return OpenAI(api_key=api_key)

    def build_system_prompt(self, policy: Any) -> str:
        """정책 카테고리에 맞는 시스템 프롬프트(공통 프리앰블 + 카테고리 특성)를 조립한다."""
        profile = CATEGORY_PROFILES.get(
            getattr(policy, "category", "default"), CATEGORY_PROFILES["default"]
        )
        preamble = profile.system_preamble or COMMON_SYSTEM_PREAMBLE
        return preamble + "\n" + profile.system_body

    def generate(
        self,
        persona: dict[str, Any],
        policy: PolicyBrief,
        rag_docs: list[RagDocument],
    ) -> dict[str, Any]:
        prompt = self.prompt_builder.build_user_prompt(persona, policy, rag_docs)
        system_prompt = self.build_system_prompt(policy)
        last_error: Exception | None = None
        for attempt in range(self.max_retries + 1):
            try:
                return self._generate_once(system_prompt, prompt)
            except Exception as exc:  # noqa: BLE001
                last_error = exc
                if attempt >= self.max_retries:
                    break
                time.sleep(self.retry_sleep_seconds * (attempt + 1))
        raise RuntimeError(f"OpenAI API 호출 실패: {last_error}") from last_error

    def _generate_once(self, system_prompt: str, prompt: str) -> dict[str, Any]:
        response = self.client.responses.create(
            model=self.model,
            input=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": prompt},
            ],
            text={
                "format": {
                    "type": "json_schema",
                    "name": "persona_policy_reaction",
                    "schema": self.JSON_SCHEMA,
                    "strict": True,
                }
            },
            temperature=0.9,
            max_output_tokens=450,
        )
        content = getattr(response, "output_text", None)
        if not content:
            content = self._extract_response_text(response)
        return self._loads_json(content)

    def _extract_response_text(self, response: Any) -> str:
        output = getattr(response, "output", None) or []
        chunks: list[str] = []
        for item in output:
            if isinstance(item, dict):
                contents = item.get("content", [])
            else:
                contents = getattr(item, "content", []) or []
            for content in contents:
                if isinstance(content, dict):
                    text = content.get("text")
                else:
                    text = getattr(content, "text", None)
                if text:
                    chunks.append(text)
        return "\n".join(chunks)

    def _loads_json(self, content: str | None) -> dict[str, Any]:
        if not content:
            raise ValueError("OpenAI 응답 텍스트가 비어 있습니다.")
        try:
            return json.loads(content)
        except json.JSONDecodeError:
            match = re.search(r"\{.*\}", content, flags=re.DOTALL)
            if not match:
                raise
            return json.loads(match.group(0))


class LocalHeuristicPersonaReactionClient:
    SUPPORTIVE_TERMS = {
        "청년": ["청년", "취업", "창업", "교육", "디지털", "일자리"],
        "노년기": ["노인", "어르신", "돌봄", "의료", "복지", "건강"],
        "교통": ["교통", "버스", "셔틀", "이동", "정류장"],
        "소득": ["일자리", "취업", "지원금", "소득", "생계", "경제"],
        "디지털": ["디지털", "스마트폰", "온라인", "앱", "교육"],
    }

    def generate(
        self,
        persona: dict[str, Any],
        policy: PolicyBrief,
        rag_docs: list[RagDocument],
    ) -> dict[str, Any]:
        demo = persona.get("demographics", {})
        traits = persona.get("policy_relevant_traits", {})
        text = policy.full_text()
        score = 3
        keyword = "생활편의"
        reasons: list[str] = []

        life_stage = self._trait_level(traits, "life_stage")
        if life_stage == "청년기" and self._contains(text, self.SUPPORTIVE_TERMS["청년"]):
            score += 1
            keyword = "청년지원"
            reasons.append("청년기 이해와 직접 연결됨")
        if life_stage == "노년기" and self._contains(text, self.SUPPORTIVE_TERMS["노년기"]):
            score += 1
            keyword = "돌봄"
            reasons.append("노년층 생활 필요와 연결됨")
        if self._contains(text, self.SUPPORTIVE_TERMS["교통"]):
            keyword = "교통"
            if self._trait_level(traits, "mobility_constraint") in {"중간", "높음"}:
                score += 1
                reasons.append("이동 불편 완화 가능성이 있음")
        if self._contains(text, self.SUPPORTIVE_TERMS["소득"]):
            keyword = "소득"
            if self._trait_level(traits, "income_insecurity") == "높음":
                score += 1
                reasons.append("소득 불안 완화 기대가 있음")
        if self._contains(text, self.SUPPORTIVE_TERMS["디지털"]):
            keyword = "디지털"
            if self._trait_level(traits, "digital_accessibility") == "낮음":
                score -= 1
                reasons.append("디지털 접근성 부담이 있음")

        if self._contains(text, ["세금", "부담금", "유료", "자부담"]):
            score -= 1
            keyword = "비용"
            reasons.append("개인 부담 가능성이 있음")

        score = max(1, min(5, score))
        stance = self._stance_from_score(score)
        opinion = self._build_opinion(persona, policy, keyword, score)
        return {
            "satisfaction_score": score,
            "stance": stance,
            "summary_keyword": keyword,
            "opinion_text": opinion,
            "reasoning_basis": ", ".join(reasons) if reasons else "정책 효과가 아직 체감 조건에 달려 있음",
            "used_rag_ids": [doc.rag_id for doc in rag_docs[:2]],
        }

    def _build_opinion(
        self,
        persona: dict[str, Any],
        policy: PolicyBrief,
        keyword: str,
        score: int,
    ) -> str:
        demo = persona.get("demographics", {})
        region = persona.get("region_name_kr") or "화순"
        age = demo.get("age", "")
        if score >= 4:
            return f"{region}에서 사는 {age}세 입장에선 {keyword}에 도움이 되면 꽤 반가운 정책입니다."
        if score == 3:
            return f"{region} 주민으로서 취지는 이해하지만 {keyword} 실행 방식이 구체적이어야 믿겠습니다."
        return f"{region}에서 살다 보니 {keyword} 부담이 커질까 봐 이 정책은 아직 걱정이 앞섭니다."

    def _contains(self, text: str, terms: list[str]) -> bool:
        return any(term in text for term in terms)

    def _trait_level(self, traits: dict[str, Any], trait_name: str) -> str | None:
        trait = traits.get(trait_name, {})
        return trait.get("level") if isinstance(trait, dict) else None

    def _stance_from_score(self, score: int) -> str:
        return {
            1: "반대",
            2: "조건부 반대",
            3: "중립",
            4: "조건부 찬성",
            5: "찬성",
        }[score]


class HwasunPersonaPolicySimulator:
    def __init__(
        self,
        persona_path: str | Path = DEFAULT_PERSONA_PATH,
        db_path: str | Path = DEFAULT_DB_PATH,
        output_path: str | Path = DEFAULT_OUTPUT_PATH,
        model: str = "gpt-4.1-mini",
        use_api: bool = True,
        api_key_env: str = "OPENAI_API_KEY",
        calibrate_satisfaction: bool = False,
    ):
        self.persona_path = Path(persona_path)
        self.db_path = Path(db_path)
        self.output_path = Path(output_path)
        self.model = model
        self.use_api = use_api
        self.api_key_env = api_key_env
        self.calibrate_satisfaction = calibrate_satisfaction
        self.parser = PolicyInputParser()

    def run(
        self,
        policy_text: str,
        persona_limit: int | None = None,
        rag_limit: int = 3,
        print_rows: bool = True,
    ) -> dict[str, Any]:
        policy = self.parser.parse(policy_text)
        if print_rows:
            profile = CATEGORY_PROFILES.get(policy.category, CATEGORY_PROFILES["default"])
            print(f"[카테고리 감지] 입력 → '{policy.category}' ({profile.label}) 특성 프롬프트 활성화")
        if self.calibrate_satisfaction:
            raise RuntimeError(
                "--calibrate-satisfaction은 더 이상 지원하지 않습니다. "
                "실제 분포 검증은 wasserstein_baseline_check.py가 CSV를 읽어 수행합니다."
            )
        personas = self.load_personas()
        if persona_limit is not None:
            personas = personas[:persona_limit]

        client = self._build_reaction_client()
        reactions: list[PersonaReaction] = []

        with HwasunRagStore(self.db_path) as rag_store:
            for idx, persona in enumerate(personas, start=1):
                keyword_docs = rag_store.search_for_persona(policy, persona, limit=rag_limit)
                # 증거팩(읍면 기반 배급) — 검색이 아니라 사전 배정된 근거를 추가로 합침.
                # cluster_name이 아직 없는 100명 단계라 policy_relevant_traits로 이슈를
                # 근사 추정하고, trait으로 안 잡히면 policy.search_keywords로 fallback.
                try:
                    pack = build_pack_for_persona(str(self.db_path), persona,
                                                   policy_keywords=policy.search_keywords)
                    evidence_docs = evidence_pack_cards_to_rag_docs(pack)
                except Exception as exc:  # noqa: BLE001 - 증거팩 실패해도 기존 파이프라인은 계속 돌아야 함
                    print(f"[증거팩 경고] {persona.get('persona_id', '?')} 생성 실패: {exc}", file=sys.stderr)
                    evidence_docs = []
                rag_docs = evidence_docs + keyword_docs
                raw_reaction = client.generate(persona, policy, rag_docs)
                reaction = self._normalize_reaction(persona, raw_reaction, rag_docs, client)
                reactions.append(reaction)
                if print_rows:
                    print(
                        f"{idx:03d}. {reaction.persona_id} "
                        f"({reaction.region_name_kr}, {reaction.age}세) "
                        f"{reaction.satisfaction_score}점 / {reaction.summary_keyword}: "
                        f"{reaction.opinion_text}"
                    )
                    self._print_rag_docs(rag_docs)

        payload = self._build_output_payload(policy, reactions)
        self.save_results(payload)
        self.save_csv(reactions)
        return payload

    def _print_rag_docs(self, rag_docs: list[RagDocument]) -> None:
        """의견 바로 아래에, 대표 선정근거 3개와 선정 사유만 출력한다."""
        if not rag_docs:
            print("     └ 근거 문서: 매칭된 RAG 문서 없음")
            return
        for doc_no, doc in enumerate(self._representative_rag_docs(rag_docs), start=1):
            title = doc.title or doc.doc_id
            print(f"     └ 선정근거{doc_no} [{doc.source_type}] {title}")
            print(f"        사유: {doc.match_reason}")

    def _representative_rag_docs(self, rag_docs: list[RagDocument], limit: int = 3) -> list[RagDocument]:
        priority_groups = [
            {"minwon", "실제민원"},
            {"policy_plan", "정책계획(Before)"},
            {"minwon", "실제민원", "policy_plan", "정책계획(Before)"},
            {"town_promise", "읍면공약"},
            {"village_knowledge", "생활격차지표", "지역지표"},
            {"policy_news", "관련뉴스", "ordinance", "조례"},
        ]
        selected: list[RagDocument] = []
        used_ids: set[str] = set()
        for group in priority_groups:
            group_docs = [
                doc for doc in rag_docs
                if doc.rag_id not in used_ids and doc.source_type in group
            ]
            if not group_docs:
                continue
            keyword_docs = [doc for doc in group_docs if "정책키워드=" in doc.match_reason]
            doc = keyword_docs[0] if keyword_docs else group_docs[0]
            selected.append(doc)
            used_ids.add(doc.rag_id)
            if len(selected) >= limit:
                return selected

        remaining_docs = [doc for doc in rag_docs if doc.rag_id not in used_ids]
        remaining_docs.sort(key=lambda doc: "정책키워드=" not in doc.match_reason)
        for doc in remaining_docs:
            selected.append(doc)
            if len(selected) >= limit:
                break
        return selected

    def _build_reaction_client(self) -> Any:
        if self.use_api:
            return OpenAIPersonaReactionClient(model=self.model, api_key_env=self.api_key_env)
        return LocalHeuristicPersonaReactionClient()

    def load_personas(self) -> list[dict[str, Any]]:
        if not self.persona_path.exists():
            raise FileNotFoundError(f"페르소나 JSON을 찾을 수 없습니다: {self.persona_path}")
        with self.persona_path.open("r", encoding=UTF8_SIG) as f:
            raw = json.load(f)

        if isinstance(raw, dict):
            if isinstance(raw.get("personas"), list):
                return raw["personas"]
            if isinstance(raw.get("data"), list):
                return raw["data"]
        if isinstance(raw, list):
            return raw
        raise ValueError("지원하지 않는 페르소나 JSON 구조입니다.")

    def _normalize_reaction(
        self,
        persona: dict[str, Any],
        raw: dict[str, Any],
        rag_docs: list[RagDocument],
        client: Any,
    ) -> PersonaReaction:
        demo = persona.get("demographics", {})
        score = int(raw.get("satisfaction_score", 3))
        score = max(1, min(5, score))
        # 새 포맷(one_line_opinion / key_keywords) 우선, 구 포맷(opinion_text / summary_keyword) 호환
        opinion = self._one_line(
            str(raw.get("one_line_opinion") or raw.get("opinion_text") or "").strip()
        )
        if not opinion:
            opinion = "정책 취지는 이해하지만 실제 생활에서 체감될지 더 지켜보고 싶습니다."
        keywords = raw.get("key_keywords")
        if isinstance(keywords, list) and keywords:
            summary_keyword = ", ".join(str(k).strip() for k in keywords if str(k).strip())
        else:
            summary_keyword = str(raw.get("summary_keyword") or "정책")
        return PersonaReaction(
            persona_id=str(persona.get("persona_id", "")),
            region_name_kr=str(persona.get("region_name_kr") or persona.get("region_code", "")),
            age=self._to_int_or_none(demo.get("age")),
            sex=str(demo.get("sex", "")),
            occupation=str(demo.get("occupation", "")),
            satisfaction_score=score,
            stance=str(raw.get("stance") or self._stance_from_score(score)),
            summary_keyword=summary_keyword or "정책",
            opinion_text=opinion,
            reasoning_basis=str(raw.get("reasoning_basis") or ""),
            used_rag_ids=self._normalize_rag_ids(raw.get("used_rag_ids"), rag_docs),
            generation_method="openai_api" if isinstance(client, OpenAIPersonaReactionClient) else "local_heuristic",
        )

    def _build_output_payload(
        self,
        policy: PolicyBrief,
        reactions: list[PersonaReaction],
    ) -> dict[str, Any]:
        scores = [reaction.satisfaction_score for reaction in reactions]
        distribution = {str(score): scores.count(score) for score in range(1, 6)}
        average = round(sum(scores) / len(scores), 3) if scores else None
        return {
            "policy": policy.to_dict(),
            "summary": {
                "persona_count": len(reactions),
                "average_satisfaction": average,
                "score_distribution": distribution,
            },
            "results": [asdict(reaction) for reaction in reactions],
        }

    def save_results(self, payload: dict[str, Any]) -> None:
        self.output_path.parent.mkdir(parents=True, exist_ok=True)
        with self.output_path.open("w", encoding=UTF8_SIG) as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)

    def save_csv(self, reactions: list[PersonaReaction]) -> None:
        csv_path = self.output_path.with_suffix(".csv")
        with csv_path.open("w", encoding=UTF8_SIG, newline="") as f:
            writer = csv.DictWriter(
                f,
                fieldnames=[
                    "persona_id",
                    "region_name_kr",
                    "age",
                    "sex",
                    "occupation",
                    "satisfaction_score",
                    "stance",
                    "summary_keyword",
                    "opinion_text",
                    "reasoning_basis",
                    "used_rag_ids",
                    "generation_method",
                ],
            )
            writer.writeheader()
            for reaction in reactions:
                row = asdict(reaction)
                row["used_rag_ids"] = "|".join(reaction.used_rag_ids)
                writer.writerow(row)

    def _normalize_rag_ids(self, raw_ids: Any, rag_docs: list[RagDocument]) -> list[str]:
        valid = {doc.rag_id for doc in rag_docs}
        if isinstance(raw_ids, list):
            cleaned = [str(item) for item in raw_ids if str(item) in valid]
            if cleaned:
                return cleaned
        return [doc.rag_id for doc in rag_docs[:2]]

    def _one_line(self, text: str) -> str:
        text = re.sub(r"\s+", " ", text).strip()
        return text[:120].rstrip()

    def _to_int_or_none(self, value: Any) -> int | None:
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def _stance_from_score(self, score: int) -> str:
        return {
            1: "반대",
            2: "조건부 반대",
            3: "중립",
            4: "조건부 찬성",
            5: "찬성",
        }[score]


def read_policy_text(args: argparse.Namespace) -> str:
    if args.policy_text:
        return args.policy_text
    if args.policy_file:
        return Path(args.policy_file).read_text(encoding=UTF8_SIG)
    if not sys.stdin.isatty():
        piped = sys.stdin.read().strip()
        if piped:
            return piped

    try:
        policy_text = input("정책을 입력하시오: ").strip()
    except EOFError as exc:
        raise ValueError(
            "정책 입력이 필요합니다. 터미널에서 실행하거나 --policy-text 또는 --policy-file을 사용하세요."
        ) from exc

    if not policy_text:
        raise ValueError("정책 입력이 비어 있습니다.")
    return policy_text


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="화순군 100인 페르소나가 정책 의견 한 줄과 5점 만족도를 생성합니다."
    )
    parser.add_argument("--policy-text", help="직접 입력할 정책 텍스트")
    parser.add_argument("--policy-file", help="정책 텍스트 파일 경로")
    parser.add_argument("--persona-path", default=str(DEFAULT_PERSONA_PATH))
    parser.add_argument("--db-path", default=str(DEFAULT_DB_PATH))
    parser.add_argument("--output", default=str(DEFAULT_OUTPUT_PATH))
    parser.add_argument("--model", default=os.getenv("OPENAI_MODEL", "gpt-4.1-mini"))
    parser.add_argument("--api-key-env", default="OPENAI_API_KEY")
    parser.add_argument("--persona-limit", type=int, default=None, help="테스트용 페르소나 수 제한")
    parser.add_argument("--rag-limit", type=int, default=3)
    parser.add_argument(
        "--no-api",
        action="store_true",
        help="OpenAI API 없이 로컬 휴리스틱으로 결과를 생성합니다.",
    )
    parser.add_argument(
        "--quiet",
        action="store_true",
        help="100명 개별 출력 없이 파일만 저장합니다.",
    )
    parser.add_argument(
        "--calibrate-satisfaction",
        action="store_true",
        help="지원 중단: 실제 설문 비율 검증은 wasserstein_baseline_check.py의 CSV 평가로 수행합니다.",
    )
    parser.add_argument(
        "--baseline-check",
        action="store_true",
        help="결과 JSON 저장 후 CSV 기준 Wasserstein 검증을 함께 실행합니다.",
    )
    parser.add_argument("--baseline-target-csv", default=str(DEFAULT_TARGET_CSV_PATH), help="실제 만족도 CSV 경로")
    parser.add_argument("--baseline-trials", type=int, default=10000, help="baseline 랜덤 반복 횟수")
    parser.add_argument("--baseline-seed", type=int, default=42, help="baseline 랜덤 시드")
    parser.add_argument(
        "--baseline-threshold",
        type=float,
        default=0.3,
        help="baseline 판정 기준(Wsim / Wrandom)",
    )
    return parser


def main() -> None:
    load_env_file()
    args = build_arg_parser().parse_args()
    try:
        policy_text = read_policy_text(args)
    except ValueError as exc:
        print(f"실행 중단: {exc}", file=sys.stderr)
        raise SystemExit(1) from exc

    simulator = HwasunPersonaPolicySimulator(
        persona_path=args.persona_path,
        db_path=args.db_path,
        output_path=args.output,
        model=args.model,
        use_api=not args.no_api,
        api_key_env=args.api_key_env,
        calibrate_satisfaction=args.calibrate_satisfaction,
    )
    try:
        payload = simulator.run(
            policy_text=policy_text,
            persona_limit=args.persona_limit,
            rag_limit=args.rag_limit,
            print_rows=not args.quiet,
        )
    except RuntimeError as exc:
        print(f"실행 중단: {exc}", file=sys.stderr)
        print("API 없이 구조만 테스트하려면 --no-api 옵션을 붙이세요.", file=sys.stderr)
        raise SystemExit(1) from exc

    summary = payload["summary"]
    total = summary["persona_count"]
    distribution = summary["score_distribution"]

    print("\n" + "=" * 46)
    print(f" 화순군 페르소나 {total}명 만족도 분포")
    print("=" * 46)
    labels = {
        "1": "매우 불만족",
        "2": "불만족   ",
        "3": "보통/조건부",
        "4": "만족   ",
        "5": "매우 만족 ",
    }
    for score in range(1, 6):
        count = distribution.get(str(score), 0)
        ratio = (count / total * 100) if total else 0
        bar = "█" * count
        print(
            f" {score}점 {labels[str(score)]} | {bar} {count:>3}명 "
            f"({ratio:4.1f}%)"
        )
    print("-" * 46)
    print(f" 평균 만족도: {summary['average_satisfaction']} / 5.0  (총 {total}명)")
    print("=" * 46)

    print("\n완료")
    print(f"- JSON 출력: {Path(args.output).resolve()}")
    print(f"- CSV 출력: {Path(args.output).with_suffix('.csv').resolve()}")

    if args.baseline_check:
        print()
        baseline_report = build_csv_wasserstein_reports(
            result_path=args.output,
            target_csv=args.baseline_target_csv,
            trials=args.baseline_trials,
            seed=args.baseline_seed,
            threshold=args.baseline_threshold,
        )
        print_csv_wasserstein_reports(baseline_report)


if __name__ == "__main__":
    main()
